PAGE = dict(
    slug='y_label_rotation',
    title='Pane::y_label_rotation',
    signature='Pane& Pane::y_label_rotation(double degrees)\nPane& Pane::clear_y_label_rotation() noexcept',
    intro='Rotates the y axis label by an explicit angle in degrees. The angle is stored in `y_axis().label_rotation_deg` as an optional value: empty until set, which means the renderer chooses the angle for the axis. `y_label_rotation` stores the angle and `clear_y_label_rotation()` removes it, restoring the automatic choice, so a figure that sets and then clears an angle is exactly the figure that never set one.\n\nThe angle must be finite. Infinity and NaN are refused with `pluss::Error` and the stored value is left as it was; every finite number is stored as given, so 90, -90 and 720 are all accepted and are not reduced to a range. It is per axis, and it is read when the figure is rendered.\n\nSetting the angle is also a way of keeping the label where you want it. A y label left to default placement turns vertical and moves beside the axis once its upright width passes `y_label_upright_max_width_share` of the pane (see [`y_label`](y_label.md)); a label with an angle of its own is never moved, so `y_label_rotation(0.0)` keeps a long label upright.',
    parameters='**degrees** (`double`)\n    The angle in degrees. Finite.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='Default, set, clear. A new pane has no override (`label_rotation_deg` is empty); the call stores the angle exactly as given, and `clear_y_label_rotation()` removes it.',
             code='auto fig = studio("y_label_rotation_readback");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nauto show = [&] { const auto& v = pane.y_axis().label_rotation_deg; std::cout << (v ? std::to_string(*v) : std::string("none")) << "\\n"; };\nstd::cout << "new pane: "; show();\npane.y_label_rotation(45.0);\nstd::cout << "after y_label_rotation(45): "; show();\npane.clear_y_label_rotation();\nstd::cout << "after clear_y_label_rotation(): "; show();\nfig.show();'),
        dict(id='angles', text='Any finite angle. The values 0, 45, 90, -90 and 720 are all accepted and stored as given, with no normalisation; the saved figure is rotated 45 degrees.',
             code='auto fig = studio("y_label_rotation_angles");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Axis label");\nfor (double degrees : {0.0, 45.0, 90.0, -90.0, 720.0}) {\n  pane.y_label_rotation(degrees);\n  std::cout << degrees << " stored as " << *pane.y_axis().label_rotation_deg << "\\n";\n}\npane.y_label_rotation(45.0);\nfig.show();'),
        dict(id='effect', text='The effect. Rotating changes the figure, and the rotated text carries a rotation in the SVG; the angle 0 equals the figure with no override.',
             code='auto build = [&](const char* mode) {\n  auto fig = studio("y_label_rotation_effect");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.y_label("Axis label");\n  if (std::string(mode) == "0") pane.y_label_rotation(0.0);\n  if (std::string(mode) == "60") pane.y_label_rotation(60.0);\n  return fig.to_svg();\n};\nstd::cout << "60 differs from none: " << (build("60") != build("none")) << ", rotate() present: " << (build("60").find("rotate(60") != std::string::npos) << "\\n";\nstd::cout << "explicit 0 equals none: " << (build("0") == build("none")) << "\\n";\nauto fig = studio("y_label_rotation_effect_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Axis label");\npane.y_label_rotation(60.0);\nfig.show();'),
        dict(id='invalid', text='Only finite angles. Infinity and NaN are refused with `pluss::Error` and the stored angle is kept; every finite number is accepted.',
             code='auto fig = studio("y_label_rotation_invalid");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Axis label");\npane.y_label_rotation(30.0);\nfor (double bad : {std::numeric_limits<double>::infinity(), -std::numeric_limits<double>::infinity(), std::numeric_limits<double>::quiet_NaN()}) {\n  try {\n    pane.y_label_rotation(bad);\n  } catch (const pluss::Error& e) {\n    std::cout << bad << ": " << e.message() << "\\n";\n  }\n}\nstd::cout << "kept: " << *pane.y_axis().label_rotation_deg << "\\n";\nfig.show();'),
        dict(id='clear_restores', text='Clearing restores the default. After `clear_y_label_rotation()` the figure equals the one that never set an angle.',
             code='auto build = [&](bool set_then_clear) {\n  auto fig = studio("y_label_rotation_clear");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.y_label("Axis label");\n  if (set_then_clear) pane.y_label_rotation(75.0).clear_y_label_rotation();\n  return fig.to_svg();\n};\nstd::cout << "equal: " << (build(true) == build(false)) << "\\n";\nauto fig = studio("y_label_rotation_clear_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Axis label");\nfig.show();'),
        dict(id='long_label', text='A rotation set by hand switches off the automatic turning of a long label. Left alone, a long y label turns vertical and sits beside the axis; with `y_label_rotation(0.0)` it stays upright at the top, as you asked, and the pane makes room for it at the left.',
             code='auto build = [&](bool by_hand) {\n  auto fig = studio("y_label_rotation_long");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{3, 5, 4, 6});\n  pane.y_label("Average household income per adult in the region (USD per year)");\n  if (by_hand) pane.y_label_rotation(0.0);\n  return fig.to_svg();\n};\nauto look = [](const std::string& svg, const std::string& text) {\n  const auto hit = svg.find(">" + text + "<");\n  if (hit == std::string::npos) return std::string("absent");\n  const auto open = svg.rfind("<text", hit);\n  const std::string tag = svg.substr(open, hit - open);\n  const auto anchor = tag.find("text-anchor=\\"");\n  std::string out = "anchor " + tag.substr(anchor + 13, tag.find(\'"\', anchor + 13) - anchor - 13);\n  const auto rot = tag.find("rotate(");\n  out += rot == std::string::npos ? ", upright" : ", rotated " + tag.substr(rot + 7, tag.find(\' \', rot) - rot - 7);\n  return out;\n};\nconst std::string longer = "Average household income per adult in the region (USD per year)";\nstd::cout << "left alone:          " << look(build(false), longer) << "\\n";\nstd::cout << "y_label_rotation(0): " << look(build(true), longer) << "\\n";\nauto fig = studio("y_label_rotation_long_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{3, 5, 4, 6});\npane.y_label("Average household income per adult in the region (USD per year)").y_label_rotation(0.0);\nfig.show();'),
    ],
    notes='- `y_label_rotation` throws, so it is not `noexcept`; `clear_y_label_rotation` never throws.\n- Rotated text needs room: the gap between the axis and its labels is set with [`y_label_gap`](y_label_gap.md).',
    see=['[`Pane::y_tick_rotation`](y_tick_rotation.md): the other rotation.', '[`Pane::x_label_rotation`](x_label_rotation.md): the same setting for the x axis.', '[`Pane::z_label_rotation`](z_label_rotation.md): the same setting for the z axis.'],
)
